#include <bits/stdc++.h>
using namespace std;

int n;
string s;
vector<int> totalCount(3, 0);
vector<vector<int>> positions(3);
vector<vector<vector<int>>> prefixFreq;

int minSteps(int v, int k, int s, int last, const vector<int>& totalCount, const vector<vector<int>>& positions, const vector<vector<int>>& prefixFreq, vector<vector<vector<vector<int>>>>& memo) {
    int cv=totalCount[0], ck=totalCount[1], cs=totalCount[2];
    if (v==cv && k==ck && s==cs) return 0;
    if (memo[v][k][s][last] != -1) return memo[v][k][s][last];

    int res = INT_MAX / 2;
    if (v<cv) {
        int p=positions[0][v];
        int move= max(prefixFreq[p][0]-v,0)+max(prefixFreq[p][1]-k,0)+max(prefixFreq[p][2]-s,0)-1;
        res = min(res, minSteps(v+1,k,s,0, totalCount, positions, prefixFreq, memo)+move);
    }
    if (k<ck && last !=0) {
        int p=positions[1][k];
        int move= max(prefixFreq[p][0]-v,0)+max(prefixFreq[p][1]-k,0)+max(prefixFreq[p][2]-s,0)-1;
        res = min(res, minSteps(v,k+1,s,1, totalCount, positions, prefixFreq, memo)+move);
    }
    if (s<cs) {
        int p=positions[2][s];
        int move= max(prefixFreq[p][0]-v,0)+max(prefixFreq[p][1]-k,0)+max(prefixFreq[p][2]-s,0)-1;
        res = min(res, minSteps(v,k,s+1,2, totalCount, positions, prefixFreq, memo)+move);
    }
    return memo[v][k][s][last]=res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> s;
    vector<char> chars(n);
    for (int i=0; i<n; i++) cin >> chars[i];

    totalCount = {0,0,0};
    positions = vector<vector<int>>(3);
    prefixFreq = vector<vector<vector<int>>>(n+1, vector<vector<int>>(3, vector<int>(1,0)));

    for (int i=0; i<n; i++) {
        prefixFreq[i+1] = prefixFreq[i];
        char ch=chars[i];
        if (ch=='V') {
            prefixFreq[i+1][0][0]++;
            totalCount[0]++;
            positions[0].push_back(i+1);
        } else if (ch=='K') {
            prefixFreq[i+1][1][0]++;
            totalCount[1]++;
            positions[1].push_back(i+1);
        } else {
            prefixFreq[i+1][2][0]++;
            totalCount[2]++;
            positions[2].push_back(i+1);
        }
    }

    vector<vector<vector<vector<int>>>> memo(
        totalCount[0]+1,
        vector<vector<vector<int>>>(
            totalCount[1]+1,
            vector<vector<int>>(
                totalCount[2]+1,
                vector<int>(3, -1)
            )
        )
    );

    cout << minSteps(0,0,0,2, totalCount, positions, prefixFreq, memo) << "\n";

    return 0;
}

